-- Secret area format:
-- {entry_x,entry_y,room_x,room_y,exit_x,exit_y,return_x,return_y,gem_x,gem_y,name}
local function add_secret(stage_i,entry_x,entry_y,name)
  local s=StageData.stages[stage_i]
  local oldw=s.width
  local room=oldw+70
  s.width=oldw+340
  s.secret={entry_x,entry_y,room+20,220,room+235,220,entry_x-24,entry_y,room+138,174,name}
  table.insert(s.solids,{room,260,270,36})
  table.insert(s.solids,{room+48,214,72,14})
  table.insert(s.solids,{room+145,188,72,14})
  table.insert(s.solids,{room+205,232,45,12})
  table.insert(s.coins,{room+72,190})
  table.insert(s.coins,{room+172,164})
  table.insert(s.coins,{room+225,208})
end

